∀ (w1 w2 s1 s2 omega_min gamma r_c Delta_eta : ℝ),
  omega_min ≤ w1 →
    omega_min ≤ w2 →
      0 < omega_min →
        0 < gamma →
          gamma ^ 2 ≤ (s1 - s2) ^ 2 →
            have r1 := r_c + Delta_eta * s1;
            have r2 := r_c + Delta_eta * s2;
            have k0 := w1 + w2;
            have k1 := w1 * r1 + w2 * r2;
            have k2 := w1 * r1 ^ 2 + w2 * r2 ^ 2;
            have k3 := w1 * r1 ^ 3 + w2 * r2 ^ 3;
            have mu0 := k0;
            have mu1 := k1 - r_c * k0;
            have mu2 := k2 - 2 * r_c * k1 + r_c ^ 2 * k0;
            have mu3 := k3 - 3 * r_c * k2 + 3 * r_c ^ 2 * k1 - r_c ^ 3 * k0;
            have det_confluent := w1 * w2 * (s1 - s2) ^ 4;
            (mu0 = w1 + w2 ∧
                mu1 = Delta_eta * (w1 * s1 + w2 * s2) ∧
                  mu2 = Delta_eta ^ 2 * (w1 * s1 ^ 2 + w2 * s2 ^ 2) ∧
                    mu3 = Delta_eta ^ 3 * (w1 * s1 ^ 3 + w2 * s2 ^ 3)) ∧
              omega_min ^ 2 * gamma ^ 4 ≤ det_confluent ∧ 0 < det_confluent

