\begin{corollary}[Plug-in upper bound with unknown primitives $(p^*,\kappa,a)$]
\label{cor:unknown_primitives}
Suppose the fundamental value $p^*$, price impact $\kappa\in[\underline{\kappa},\overline{\kappa}]\subset(0,\infty)$, and persistence $a\in[0,\bar{a}]\subset[0,1)$ are unknown to the observer. Subtracting the pre-probe price $p_{n,0}=p^*+\nu_{n,-1}$ eliminates $p^*$ (doubling observation noise variance to $2\sigma^2$), and $\hat{\kappa}=\hat{h}_0$ estimates $\kappa$ from the impact tap $h_0 = \kappa$ with $|\hat{\kappa}-\kappa|\le\sigma N^{-1/2}\sqrt{2\log(8K/\beta)}$. Since the lag-1 response satisfies $h_1 = a\kappa + \kappa^2 k_0$, any $\sqrt{N}$-consistent estimator of $a$ with $|\hat{a}-a|\le C_a\sigma N^{-1/2}\sqrt{2\log(8K/\beta)}$ (for example from lag-0 and lag-1 taps, a pre-probe free-decay step, or regressing price changes on aggregate anonymous order flow under contract $I_1$) can be plugged in: replacing $(a,\kappa)$ by $(\hat{a},\hat{\kappa})$ in the closed-loop deconvolution of Theorem~\ref{prop:esprit} yields
\[
\max_{0\le m\le 2K-1}|\hat{k}_m^{\mathrm{plug}}-\hat{k}_m|\le L_{a,\kappa}\big(|\hat{a}-a|+|\hat{\kappa}-\kappa|\big)\le C_{a,\kappa}\sigma N^{-1/2}\sqrt{\log(8K/\beta)}
\]
with probability at least $1-\beta/2$, where $L_{a,\kappa}<\infty$ depends only on $(K,\underline{\kappa},\overline{\kappa},\bar{a},W)$ and not on $\Delta\eta$. Consequently, Prony's method with plug-in $(\hat{a},\hat{\kappa})$ achieves the exact same minimax sample complexity $N=C''\sigma^2(\Delta\eta)^{-(4K-2)}$ as when $(p^*,\kappa,a)$ are known.
\end{corollary}

\begin{theorem}[Passive identification: minimum phase]\label{thm:minphase}
In a stable economy with $0<a<1$, distinct $0<r_i<1$ and nonzero merged weights, the zeros of $H$ are the memory rates $r_i$ together with a structural zero at $z=0$, and $H$ is minimum phase. Degenerate anchor and zero-rate cases require the cancellations described in the merged-equivalence proof. With a single price innovation, the price spectrum identifies $H$ up to scale, hence the memory rates; with $\kappa$ and $a$ known, as in Theorem~\ref{thm:merged}, it identifies the merged measure.
\end{theorem}

historical_types.p1_thm_minphase_passive_identification:
∀ (kappa a w1 w2 r1 r2 : ℝ),
  kappa ≠ 0 →
    w1 ≠ 0 →
      r1 ≠ 0 →
        r1 ≠ r2 →
          have D := fun z => (z - r1) * (z - r2);
          have N := fun z => w1 * z * (z - r2) + w2 * z * (z - r1);
          have Denom := fun z => (z - a) * D z - kappa * N z;
          D r1 = 0 ∧ Denom r1 = -kappa * w1 * r1 * (r1 - r2) ∧ Denom r1 ≠ 0

