            0 < eta2 →
              eta2 < 1 →
                eta1 ≠ eta2 →
                  have p_minus := 1 / 2 - tau / q;
                  have p_plus := 1 / 2 + tau / q;
                  have w0_1 := q * p_minus;
                  have w0_2 := q * p_plus;
                  have e0_1 := eta_bar - p_plus * Delta_eta;
                  have e0_2 := eta_bar + p_minus * Delta_eta;
                  have w1_1 := q * p_plus;
                  have w1_2 := q * p_minus;
                  have e1_1 := eta_bar - p_minus * Delta_eta;
                  have e1_2 := eta_bar + p_plus * Delta_eta;
